create table public.profiles(id uuid primary key references auth.users on delete cascade, timezone text not null default 'Asia/Shanghai', created_at timestamptz not null default now());
create table public.subscriptions(user_id uuid primary key references auth.users on delete cascade, plan text not null default 'free' check(plan in ('free','pro')));
create table public.sources(id uuid primary key default gen_random_uuid(),name text not null,url text unique not null,status text not null default 'unknown',last_fetched_at timestamptz,error text);
create table public.articles(id uuid primary key default gen_random_uuid(),url text unique not null,title text not null,excerpt text,published_at timestamptz,updated_at timestamptz,event_at timestamptz,fetched_at timestamptz not null default now());
create table public.article_sources(article_id uuid references public.articles on delete cascade,source_id uuid references public.sources on delete cascade,primary key(article_id,source_id));
create table public.topics(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,name text not null check(length(name) between 1 and 100),keywords text[] not null default '{}',excluded text[] not null default '{}',source_ids uuid[] not null default '{}',timezone text not null default 'Asia/Shanghai',start_hour integer not null default 0 check(start_hour between 0 and 23),end_hour integer not null default 23 check(end_hour between 0 and 23),frequency text not null default 'daily' check(frequency in ('daily','hourly')),brief_time text not null default '09:00',created_at timestamptz not null default now());
create table public.topic_articles(topic_id uuid not null references public.topics on delete cascade,article_id uuid not null references public.articles on delete cascade,linked_at timestamptz not null default now(),primary key(topic_id,article_id));
create table public.saved_articles(user_id uuid not null references auth.users on delete cascade,article_id uuid not null references public.articles on delete cascade,created_at timestamptz not null default now(),primary key(user_id,article_id));
create table public.ideas(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,title text not null check(length(title) between 1 and 200),notes text not null default '' check(length(notes)<=20000),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.ai_operations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,idempotency_key uuid not null,kind text not null check(kind in ('summary','idea')),resource_id uuid not null,status text not null default 'reserved' check(status in ('reserved','succeeded','failed')),model text,parameters jsonb not null default '{}',prompt_tokens integer,completion_tokens integer,error text,created_at timestamptz not null default now(),settled_at timestamptz,unique(user_id,idempotency_key));
create table public.ai_analyses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,operation_id uuid unique not null references public.ai_operations on delete cascade,kind text not null,resource_id uuid not null,result jsonb not null,created_at timestamptz not null default now());
create table public.usage_records(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,operation_id uuid unique not null references public.ai_operations on delete cascade,kind text not null,created_at timestamptz not null default now());
create table public.monitoring_runs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,topic_id uuid references public.topics on delete cascade,status text not null default 'running' check(status in ('running','succeeded','partial','failed')),articles_count integer not null default 0,error text,created_at timestamptz not null default now(),finished_at timestamptz);
create table public.product_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,event text not null check(event in ('registered','topic_created','refresh_succeeded','ai_succeeded','feature_error','pro_waitlist')),created_at timestamptz not null default now());
create index on public.topics(user_id);
create index on public.ideas(user_id);
create index on public.ai_operations(user_id,created_at);
create index on public.monitoring_runs(user_id,created_at);
create index on public.articles(published_at);
create index on public.article_sources(source_id);
create index on public.topic_articles(article_id);
create or replace function public.new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id) values(new.id);insert into public.subscriptions(user_id) values(new.id);insert into public.product_events(user_id,event) values(new.id,'registered');return new;end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.new_user();
-- Central server plan configuration is mirrored here to enforce quotas at database boundary.
create table public.plan_limits(plan text primary key,topics integer not null,summaries integer not null,ideas integer not null,history integer not null);
insert into public.plan_limits values('free',3,3,1,7),('pro',20,50,20,90);
create function public.check_topic_limit() returns trigger language plpgsql security definer set search_path='' as $$ declare lim integer;begin perform pg_advisory_xact_lock(hashtextextended(new.user_id::text,0));select p.topics into lim from public.plan_limits p join public.subscriptions s on s.plan=p.plan where s.user_id=new.user_id;if (select count(*) from public.topics where user_id=new.user_id)>=coalesce(lim,3) then raise exception '已达到套餐主题上限';end if;return new;end $$;
create trigger topic_limit before insert on public.topics for each row execute function public.check_topic_limit();
do $$ declare t text;begin foreach t in array array['profiles','subscriptions','sources','articles','article_sources','topics','topic_articles','saved_articles','ideas','ai_analyses','usage_records','monitoring_runs','ai_operations','product_events','plan_limits'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);end loop;end $$;
grant select on public.sources,public.articles,public.article_sources,public.plan_limits to authenticated;
create policy public_sources on public.sources for select to authenticated using(true);
create policy public_articles on public.articles for select to authenticated using(true);
create policy public_article_sources on public.article_sources for select to authenticated using(true);
create policy public_limits on public.plan_limits for select to authenticated using(true);
do $$ declare t text;begin foreach t in array array['profiles','subscriptions','topics','saved_articles','ideas','ai_analyses','usage_records','monitoring_runs','ai_operations','product_events'] loop execute format('grant select on public.%I to authenticated',t);execute format('create policy own_read on public.%I for select to authenticated using ((select auth.uid()) = %I)',t,case when t='profiles' then 'id' else 'user_id' end);end loop;end $$;
grant insert,update,delete on public.topics,public.ideas,public.saved_articles to authenticated;
do $$ declare t text;begin foreach t in array array['topics','ideas','saved_articles'] loop execute format('create policy own_insert on public.%I for insert to authenticated with check ((select auth.uid())=user_id)',t);execute format('create policy own_update on public.%I for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id)',t);execute format('create policy own_delete on public.%I for delete to authenticated using ((select auth.uid())=user_id)',t);end loop;end $$;
grant select on public.topic_articles to authenticated;
create policy own_topic_articles on public.topic_articles for select to authenticated using(exists(select 1 from public.topics t where t.id=topic_id and t.user_id=(select auth.uid())));
-- Only service_role can invoke reservation and settlement. Never trust browser plan/user claims.
create function public.reserve_ai(p_user uuid,p_key uuid,p_kind text,p_resource uuid,p_model text) returns public.ai_operations language plpgsql security definer set search_path='' as $$ declare op public.ai_operations;lim integer;begin
perform pg_advisory_xact_lock(hashtextextended(p_user::text,1));
update public.ai_operations set status='failed',error='请求中断，额度已释放',settled_at=now() where user_id=p_user and status='reserved' and created_at<now()-interval '5 minutes';
select * into op from public.ai_operations where user_id=p_user and idempotency_key=p_key;
if found then if op.kind<>p_kind or op.resource_id<>p_resource then raise exception '幂等标识已用于其他请求';end if;return op;end if;
select case when p_kind='summary' then l.summaries else l.ideas end into lim from public.plan_limits l join public.subscriptions s on l.plan=s.plan where s.user_id=p_user;
if (select count(*) from public.ai_operations where user_id=p_user and kind=p_kind and status in ('reserved','succeeded') and created_at>=date_trunc('day',now() at time zone 'UTC') at time zone 'UTC')>=coalesce(lim,0) then raise exception '今日 AI 额度已用完（UTC 重置）';end if;
insert into public.ai_operations(user_id,idempotency_key,kind,resource_id,model,parameters) values(p_user,p_key,p_kind,p_resource,p_model,'{"temperature":0.3,"max_tokens":1400}') returning * into op;return op;end $$;
create function public.settle_ai(p_operation uuid,p_result jsonb,p_prompt integer,p_completion integer,p_error text default null) returns void language plpgsql security definer set search_path='' as $$ declare op public.ai_operations;begin select * into op from public.ai_operations where id=p_operation for update;if op.status<>'reserved' then return;end if;
update public.ai_operations set status=case when p_error is null then 'succeeded' else 'failed' end,prompt_tokens=p_prompt,completion_tokens=p_completion,error=p_error,settled_at=now() where id=op.id;
if p_error is null then insert into public.ai_analyses(user_id,operation_id,kind,resource_id,result) values(op.user_id,op.id,op.kind,op.resource_id,p_result);insert into public.usage_records(user_id,operation_id,kind) values(op.user_id,op.id,op.kind);insert into public.product_events(user_id,event) values(op.user_id,'ai_succeeded');end if;end $$;
revoke execute on function public.reserve_ai(uuid,uuid,text,uuid,text),public.settle_ai(uuid,jsonb,integer,integer,text),public.new_user(),public.check_topic_limit() from public,anon,authenticated;
grant execute on function public.reserve_ai(uuid,uuid,text,uuid,text),public.settle_ai(uuid,jsonb,integer,integer,text) to service_role;
